arguments.command:
node -e '
fetch("https://arb1.arbitrum.io/rpc", {
  method: "POST",
  headers: {"Content-Type": "application/json"},
  body: JSON.stringify({jsonrpc: "2.0", method: "eth_chainId", params: [], id: 1})
}).then(r => r.json()).then(console.log);
'

node -e '
fetch("https://sepolia-rollup.arbitrum.io/rpc", {
  method: "POST",
  headers: {"Content-Type": "application/json"},
  body: JSON.stringify({jsonrpc: "2.0", method: "eth_chainId", params: [], id: 1})
}).then(r => r.json()).then(console.log);
'

node -e '
fetch("https://arbiscan.io").then(r => console.log("arbiscan:", r.status));
fetch("https://sepolia.arbiscan.io").then(r => console.log("sepolia arbiscan:", r.status));
'

node -e '
console.log(process.version);
'

