  console.log("res:", res);
  if (res.result) {
    const l2Token = "0x" + res.result.slice(-40);
    console.log("calculated l2Token:", l2Token);
    // check symbol on Arb Sepolia
    const r2 = await fetch("https://sepolia-rollup.arbitrum.io/rpc", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({
        jsonrpc: "2.0",
        method: "eth_call",
        params: [{ to: l2Token, data: "0x95d89b41" }, "latest"],
        id: 2
      })
    });
    const d2 = await r2.json();
    console.log("symbol res:", d2);
    if (d2.result && d2.result !== "0x") {
      console.log("symbol:", Buffer.from(d2.result.slice(2), "hex").toString("utf8"));
    }
  }
}
test();
'

